import{_ as o,o as a,c as t,a3 as i}from"./chunks/framework.BveOjhN0.js";const u=JSON.parse('{"title":"Companies — Production Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Companies — Production Guide | SaleOS Docs"}],["meta",{"property":"og:description","content":"Official documentation for the SaleOS SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.saleos.app/deployment/companies"}],["meta",{"property":"og:image","content":"https://docs.saleos.app/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Companies — Production Guide | SaleOS Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the SaleOS SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.saleos.app/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.saleos.app/deployment/companies"}]]},"headers":[],"relativePath":"deployment/companies.md","filePath":"deployment/companies.md","lastUpdated":1785409752000}'),n={name:"deployment/companies.md"};function s(c,e,r,d,l,p){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="companies-—-production-guide" tabindex="-1">Companies — Production Guide <a class="header-anchor" href="#companies-—-production-guide" aria-label="Permalink to &quot;Companies — Production Guide&quot;">​</a></h1><h2 id="licensing" tabindex="-1">Licensing <a class="header-anchor" href="#licensing" aria-label="Permalink to &quot;Licensing&quot;">​</a></h2><ul><li>Catalog slug: <code>companies</code></li><li><strong>Free and default-included</strong> CRM module (same family as Leads/Tasks/Contacts/Calendar/Meetings)</li><li>Catalog flags: <code>is_default_included = true</code>, <code>is_billable = false</code>, price <code>0</code>, <code>sort_order = 12</code></li><li>New workspaces receive <code>module:companies</code> automatically via <code>ModuleSubscriptionService::installDefaultModules()</code> (subscription <code>source = included</code>)</li><li>Existing workspaces missing the entitlement are backfilled by the Companies registration / ensure migrations</li><li>Deactivate via Central module subscription tools to revoke access without dropping data</li></ul><h2 id="bootstrap" tabindex="-1">Bootstrap <a class="header-anchor" href="#bootstrap" aria-label="Permalink to &quot;Bootstrap&quot;">​</a></h2><p>On <strong>new workspace</strong> create (Central tenant create or public register):</p><ol><li><code>installDefaultModules()</code> installs every published <code>is_default_included</code> module, including <strong>Companies</strong></li><li>Entitlement is non-billable (<code>price = 0</code>, <code>source = included</code>)</li><li>Tenant permissions include <code>companies.*</code> via <code>config/tenant-permissions.php</code> / default role maps</li></ol><p>No stage or status seeder (unlike Leads) — Companies is a flat directory record.</p><h2 id="permissions-rollout" tabindex="-1">Permissions rollout <a class="header-anchor" href="#permissions-rollout" aria-label="Permalink to &quot;Permissions rollout&quot;">​</a></h2><p>New Companies permissions for <strong>existing</strong> workspaces must ship as an additive <strong>data migration</strong> using <code>TenantPermissionSynchronizer::grantMissingDefaultRolePermissions([...])</code>. Do <strong>not</strong> re-seed roles or rely on login/dashboard to repair RBAC.</p><h2 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h2><ul><li>Platform audit events: <code>company_created</code>, <code>company_updated</code>, <code>company_deleted</code>, <code>company_assigned</code>, <code>company_note_added</code>, <code>company_restored</code></li><li>Notifications: assignment (mail + database) via <code>CompanyAssignedNotification</code></li><li>Tenant mail settings with Central SMTP fallback</li></ul><h2 id="contact-integration" tabindex="-1">Contact integration <a class="header-anchor" href="#contact-integration" aria-label="Permalink to &quot;Contact integration&quot;">​</a></h2><p>When Companies is installed alongside Contacts, Contact create/update accept <code>company_id</code>. The legacy <code>company</code> string is synced from the linked Company name when a link is set. No automatic backfill runs for existing free-text <code>company</code> values — that job is deferred.</p><h2 id="deploy-checklist" tabindex="-1">Deploy checklist <a class="header-anchor" href="#deploy-checklist" aria-label="Permalink to &quot;Deploy checklist&quot;">​</a></h2><ol><li>Migrate company tables (<code>companies</code>, <code>company_notes</code>, <code>company_activities</code>) and <code>contacts.company_id</code></li><li>Register the <code>companies</code> catalog module (migration, not seeder) with <code>is_default_included</code> / ensure backfill for existing workspaces</li><li>Confirm <code>module:companies</code> + <code>companies.*</code> permissions on target roles</li><li>Deploy frontend (Companies nav item, list/form/detail, dashboard <strong>Recent Companies</strong> widget + <strong>Create Company</strong> quick action, Contact form company picker)</li><li>Smoke: create a <strong>new</strong> workspace → Companies appears in nav without Marketplace purchase → create/edit/assign/note a company → link a Contact via company picker → confirm <code>company_id</code> + synced <code>company</code> string</li></ol>',15)])])}const g=o(n,[["render",s]]);export{u as __pageData,g as default};
